export type LayoutProperty = "container-type" | "display" | "position" | "inset" | "top" | "bottom" | "left" | "right" | "overflow" | "overflow-x" | "overflow-y" | "overscroll-behavior" | "pointer-events" | "cursor" | "contain" | "padding" | "padding-top" | "padding-bottom" | "padding-left" | "padding-right" | "margin" | "margin-top" | "margin-bottom" | "margin-left" | "margin-right" | "background" | "border-radius" | "border-top-left-radius" | "border-top-right-radius" | "border-bottom-right-radius" | "border-bottom-left-radius" | "width" | "min-width" | "max-width" | "height" | "min-height" | "max-height" | "grid-area" | "grid-row" | "grid-column" | "order" | "flex" | "flex-grow" | "flex-shrink" | "flex-basis" | "align-self" | "justify-self" | "border-top" | "border-bottom" | "border-left" | "border-right" | "visibility" | "white-space" | "row-gap" | "column-gap" | "flex-direction" | "flex-wrap" | "justify-content" | "align-items" | "grid-template-columns" | "grid-template-rows" | "grid-template-areas" | "grid-auto-columns" | "grid-auto-rows" | "grid-auto-flow" | "align-content" | "justify-items" | "box-shadow";

